import React, { useEffect, useState } from "react";
import axios from "axios";

const CustomerDashboard = () => {
  const [listings, setListings] = useState([]);
  const [search, setSearch] = useState("");

  useEffect(() => {
    const fetchListings = async () => {
      try {
        const { data } = await axios.get("http://localhost:5000/api/listings");
        setListings(data);
      } catch (error) {
        console.error("Error fetching listings:", error);
      }
    };
    fetchListings();
  }, []);

  const filteredListings = listings.filter(
    (listing) =>
      listing.title?.toLowerCase().includes(search.toLowerCase()) ||
      listing.description?.toLowerCase().includes(search.toLowerCase())
  );

  const handleBuy = (listingId) => {
    alert(`Proceed to buy product with ID: ${listingId}`);
    // You can integrate your order or payment system here
  };

  const handleContactSeller = (sellerEmail) => {
    if (!sellerEmail) {
      alert("Seller contact information not available.");
      return;
    }
    window.location.href = `mailto:${sellerEmail}`;
  };

  return (
    <div className="p-6 bg-gray-50 min-h-screen">
      <h1 className="text-3xl font-bold mb-6 text-center text-gray-800">
        Available Listings
      </h1>

      {/* Search Bar */}
      <div className="flex justify-center mb-8">
        <input
          type="text"
          placeholder="Search listings..."
          className="border border-gray-300 rounded-lg px-4 py-2 w-1/2 shadow-sm focus:outline-none focus:ring-2 focus:ring-blue-400"
          value={search}
          onChange={(e) => setSearch(e.target.value)}
        />
      </div>

      {/* Listings */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
        {filteredListings.length > 0 ? (
          filteredListings.map((listing) => (
            <div
              key={listing._id}
              className="bg-white shadow-lg rounded-xl p-5 transition transform hover:scale-105"
            >
              <img
                src={
                  listing.image
                    ? `http://localhost:5000/${listing.image}`
                    : "/placeholder.jpg"
                }
                alt={listing.title}
                className="w-full h-48 object-cover rounded-md mb-4"
              />
              <h2 className="text-xl font-semibold text-gray-800 mb-2">
                {listing.title}
              </h2>
              <p className="text-gray-600 mb-2 line-clamp-3">
                {listing.description}
              </p>
              <p className="text-blue-600 font-bold mb-4">
                ₹{listing.price || "N/A"}
              </p>

              <div className="flex justify-between items-center">
                <button
                  onClick={() => handleBuy(listing._id)}
                  className="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-lg"
                >
                  Buy
                </button>

                <button
                  onClick={() => handleContactSeller(listing.sellerEmail)}
                  className="bg-green-600 hover:bg-green-700 text-white px-4 py-2 rounded-lg"
                >
                  Contact Seller
                </button>
              </div>
            </div>
          ))
        ) : (
          <p className="text-center text-gray-500 col-span-full">
            No listings found.
          </p>
        )}
      </div>
    </div>
  );
};

export default CustomerDashboard;
